class ReadinessT38Test {

    // ------------------------------------------------------------------ the fixture loader

    private inner class Vec(
        val kind: String,
        val name: String,
        val fields: Map<String, String>,
    ) {
        val generation: Long get() = required("generation").toLong()
        val created: Long get() = required("created_at").toLong()
        val timeQuality: Int get() = required("time_quality").toInt()
        val seed: ByteArray get() = hexBytes(required("ed25519_seed_hex"))
        val signPub: ByteArray get() = hexBytes(required("signing_public_key"))
        val dhPub: ByteArray get() = hexBytes(required("static_dh_public_key"))
        val node: ByteArray get() = hexBytes(required("node_id"))
        val nonce: ByteArray get() = hexBytes(required("nonce_hex"))
        val body: ByteArray get() = hexBytes(required("body_hex"))
        val binding: ByteArray get() = hexBytes(required("binding_hex"))
        val unsigned: ByteArray get() = hexBytes(required("unsigned_hex"))
        val msgId: ByteArray get() = hexBytes(required("msg_id_hex"))
        val signature: ByteArray get() = hexBytes(required("signature_hex"))
        val payload: ByteArray get() = hexBytes(required("frame_payload_hex"))
        val reason: String get() = required("expected_reason")
        val headerType: Int get() = required("header.type").toInt()
        val headerFlags: Int get() = required("header.flags").toInt()

        fun required(key: String): String {
            val v = fields[key]
            if (v == null || v == "null") throw AssertionError("vector " + name + " lacks " + key)
            return v
        }
    }

    private fun locateVectors(): List<Vec> {
        var dir = java.io.File(System.getProperty("user.dir"))
        while (!java.io.File(dir, "crypto").isDirectory) {
            val parent = dir.parentFile ?: throw AssertionError("no repo root above user.dir")
            dir = parent
        }
        val file = java.io.File(dir, "crypto/sos_v1_vectors.json")
        val out = ArrayList<Vec>()
        var fields: HashMap<String, String>? = null
        var kind: String? = null
        var name: String? = null
        var depthKey = ""
        for (raw in file.readLines()) {
            val line = raw.trim()
            if (line.startsWith("\"header\":")) { depthKey = "header."; continue }
            if (line == "}" || line == "},") depthKey = ""
            if (line.startsWith("\"kind\":")) {
                if (fields != null && kind != null && name != null) out.add(Vec(kind!!, name!!, fields!!))
                fields = HashMap()
                kind = valueOf(line)
                name = null
                continue
            }
            val rec = fields ?: continue
            if (line.startsWith("\"name\":")) { if (name == null) name = valueOf(line); continue }
            val at = line.indexOf("\": ")
            if (at < 0 || !line.startsWith("\"")) continue
            rec[depthKey + line.substring(1, at)] = valueOf(line)
        }
        if (fields != null && kind != null && name != null) out.add(Vec(kind!!, name!!, fields!!))
        return out
    }

    private fun valueOf(line: String): String {
        val at = line.indexOf("\": ")
        var v = line.substring(at + 3).trim()
        if (v.endsWith(",")) v = v.substring(0, v.length - 1)
        if (v.length >= 2 && v.startsWith("\"") && v.endsWith("\"")) v = v.substring(1, v.length - 1)
        return v
    }

    private fun hexBytes(text: String): ByteArray {
        val out = ByteArray(text.length / 2)
        for (k in out.indices) out[k] = text.substring(k * 2, k * 2 + 2).toInt(16).toByte()
        return out
    }

    private fun ascii(text: String): ByteArray = text.toByteArray(kotlin.text.Charsets.UTF_8)

    private fun frameOf(type: TypeV2, flags: Int, msgId: ByteArray, payload: ByteArray): FrameV2 =
        FrameV2(
            type = type,
            msgId = msgId,
            routingTag = ByteArray(4),
            ttl = FrameV2.MAX_TTL,
            hopCount = 0,
            flags = flags,
            payload = payload,
        )

    private fun quality(code: Int): TimeQuality = when (code) {
        0 -> TimeQuality.UNKNOWN
        1 -> TimeQuality.USER_CONFIRMED
        else -> TimeQuality.AUTHENTICATED_SOURCE
    }

    private fun unauthenticatedOf(result: SosAuthResult): SosAuthResult.Unauthenticated? =
        if (result is SosAuthResult.Unauthenticated) result else null

    private fun rejectWithReason(result: SosAuthResult, expected: String, label: String) {
        val bad = unauthenticatedOf(result)
        Assert.assertNotNull(label + ": the receiver must refuse", bad)
        Assert.assertEquals(label + ": named reason", expected, bad!!.reason)
    }

    private fun deadRepo(): DeliveryRepository = object : DeliveryRepository {
        override fun get(msgId: ByteArray): DeliveryLookup =
            throw NotImplementedError("the tracker path is closed to these witnesses")
        override fun enqueue(msgId: ByteArray, ackMode: AckMode, expectedRecipient: ByteArray?): EnqueueResult =
            throw NotImplementedError("the tracker path is closed to these witnesses")
        override fun transition(msgId: ByteArray, transition: DeliveryTransition): TransitionResult =
            throw NotImplementedError("the tracker path is closed to these witnesses")
        override fun acknowledgeBoundAndRetire(msgId: ByteArray, expectedRecipient: ByteArray): AckResult =
            throw NotImplementedError("the tracker path is closed to these witnesses")
        override fun clear(msgId: ByteArray): ClearResult =
            throw NotImplementedError("the tracker path is closed to these witnesses")
    }

    private class T38Journal : DeliveryRepository {
        val records = mutableMapOf<List<Byte>, DeliveryRecord>()
        private fun k(m: ByteArray) = m.toList()
        override fun get(msgId: ByteArray): DeliveryLookup {
            if (msgId.size != 16) return DeliveryLookup.InvalidArgument
            val rec = records[k(msgId)] ?: return DeliveryLookup.NotFound
            return DeliveryLookup.Found(rec)
        }
        override fun enqueue(msgId: ByteArray, ackMode: AckMode, expectedRecipient: ByteArray?): EnqueueResult {
            if (msgId.size != 16) return EnqueueResult.InvalidArgument
            if (msgId.size != 16) return EnqueueResult.InvalidArgument
            if (records.containsKey(k(msgId))) {
                val old = records[k(msgId)]!!
                if (old.ackMode == ackMode && bindingSame(old.expectedRecipientNodeId, expectedRecipient))
                    return EnqueueResult.AlreadyQueuedSameBinding
                return EnqueueResult.ConflictRecipient
            }
            records[k(msgId)] = DeliveryRecord(msgId, DeliveryState.QUEUED_DURABLY, ackMode, expectedRecipient)
            return EnqueueResult.Created
        }
        override fun transition(msgId: ByteArray, transition: DeliveryTransition): TransitionResult {
            if (msgId.size != 16) return TransitionResult.InvalidArgument
            val rec = records[k(msgId)] ?: return TransitionResult.UnknownMessage
            val target: DeliveryState
            val validFroms: Set<DeliveryState>
            when (transition) {
                DeliveryTransition.MARK_HANDED -> {
                    target = DeliveryState.HANDED_TO_RELAY
                    validFroms = setOf(DeliveryState.QUEUED_DURABLY)
                }
                DeliveryTransition.EXPIRE -> {
                    target = DeliveryState.EXPIRED
                    validFroms = setOf(DeliveryState.QUEUED_DURABLY, DeliveryState.HANDED_TO_RELAY)
                }
                DeliveryTransition.CANCEL -> {
                    target = DeliveryState.CANCELLED_LOCALLY
                    validFroms = setOf(DeliveryState.QUEUED_DURABLY, DeliveryState.HANDED_TO_RELAY)
                }
            }
            if (rec.state == target) return TransitionResult.AlreadyInTarget
            if (rec.state !in validFroms) return TransitionResult.RejectedState
            records[k(msgId)] = rec.copy(state = target)
            return TransitionResult.Applied
        }
        override fun acknowledgeBoundAndRetire(msgId: ByteArray, expectedRecipient: ByteArray): AckResult {
            if (msgId.size != 16 || expectedRecipient.size != 16) return AckResult.InvalidArgument
            val rec = records[k(msgId)] ?: return AckResult.UnknownMessage
            if (rec.ackMode != AckMode.SINGLE_RECIPIENT ||
                !rec.expectedRecipientNodeId.contentEquals(expectedRecipient)
            ) return AckResult.UnknownMessage
            if (rec.state == DeliveryState.ACKNOWLEDGED_BY_RECIPIENT) return AckResult.DuplicateAuthenticatedAck
            records[k(msgId)] = rec.copy(state = DeliveryState.ACKNOWLEDGED_BY_RECIPIENT)
            return AckResult.Applied
        }
        override fun clear(msgId: ByteArray): ClearResult {
            if (msgId.size != 16) return ClearResult.InvalidArgument
            return if (records.remove(k(msgId)) != null) ClearResult.Cleared else ClearResult.AlreadyAbsent
        }
        private fun bindingSame(a: ByteArray?, b: ByteArray?): Boolean {
            if (a == null || b == null) return a === b
            return a.contentEquals(b)
        }
        private fun ByteArray?.contentEquals(other: ByteArray?): Boolean {
            if (this == null || other == null) return this === other
            return this.contentEquals(other)
        }
    }

    private fun newIdentity(): Identity {
        val rng = SecureRandom()
        val ed = Ed25519Keys.generate(rng)
        val dh = X25519Keys.generate(rng)
        return Identity.fromKeyMaterial(ed.pub, ed.priv, dh.pub, dh.priv)
    }

    private class FakeAuthority(
        val seed: ByteArray,
        val dhPub: ByteArray,
        val generation: Long,
        val clock: Long,
        val nonce: ByteArray,
    ) : SosSigningAuthority {
        var calls = 0
        override fun currentNonce(): ByteArray { calls++; return nonce.copyOf() }
        override fun currentSigningSeed(): ByteArray = seed.copyOf()
        override fun currentStaticDhPublicKey(): ByteArray = dhPub.copyOf()
        override fun currentGeneration(): Long = generation
        override fun currentTimeEpochSeconds(): Long = clock
    }

    private class Watcher : SosObserver {
        var authenticated = 0
        var unauthenticated = 0
        var lastReason = ""
        var lastVerified: VerifiedSos? = null
        override fun onSosAuthenticated(verified: VerifiedSos) { authenticated++; lastVerified = verified }
        override fun onSosUnauthenticated(frame: FrameV2, reason: String) { unauthenticated++; lastReason = reason }
    }

    // ------------------------------------------------------------------ W1 golden vectors

    /** W1 -- author/verify across the isles: the JVM reproduces every pinned
     *  accept vector byte for byte (deterministic signer on this isle), the
     *  frozen MessageId formula holds over the UNSIGNED span, and the
     *  receiver re-authenticates the frame and resolves it to the vector's
     *  declared identity material. */
    @Test
    fun testAuthorProducesVerifiableSignatureAcrossIsles() {
        for (v in locateVectors().filter { it.kind == "accept" }) {
            val unsigned = SignedSosV1.unsignedPayload(
                v.binding, v.created, quality(v.timeQuality), v.nonce, v.body,
            )
            Assert.assertArrayEquals(v.name + ": unsigned payload", v.unsigned, unsigned)
            val mid = SignedSosV1.deriveMessageId(v.node, v.created, v.nonce, unsigned)
            Assert.assertArrayEquals(v.name + ": msg_id is the frozen formula over the unsigned span",
                v.msgId, mid)
            val transcript = SignedSosV1.signatureTranscript(mid, unsigned)
            Assert.assertEquals(v.name + ": transcript is msg_id || SOS1 || unsigned",
                mid.size + 4 + unsigned.size, transcript.size)
            val frame = SignedSosV1.author(v.seed, v.dhPub, v.generation, v.created,
                quality(v.timeQuality), v.nonce, v.body)
            Assert.assertArrayEquals(v.name + ": pinned signature", v.signature,
                frame.payload.copyOfRange(4, 68))
            Assert.assertArrayEquals(v.name + ": pinned frame payload", v.payload, frame.payload)
            Assert.assertArrayEquals(v.name + ": pinned msg_id", v.msgId, frame.msgId)
            Assert.assertEquals(v.name + ": outer type kept", TypeV2.SOS, frame.type)
            Assert.assertEquals(v.name + ": required flags kept", 0x0030, frame.flags)
            Assert.assertEquals(v.name + ": ttl at the flood ceiling", FrameV2.MAX_TTL, frame.ttl)
            Assert.assertEquals(v.name + ": hop born at zero", 0, frame.hopCount)
            Assert.assertArrayEquals(v.name + ": broadcast tag is not a hint", ByteArray(4), frame.routingTag)
            val verdict = SignedSosV1.verify(frame, v.node)
            val ok = verdict as? SosAuthResult.Authenticated
            Assert.assertNotNull(v.name + ": the receiver must accept the honest frame", ok)
            val seen = ok!!.verified
            Assert.assertArrayEquals(v.name + ": resolved sender", v.node, seen.senderNodeId)
            Assert.assertArrayEquals(v.name + ": resolved signing key", v.signPub, seen.signingPublicKey)
            Assert.assertArrayEquals(v.name + ": resolved dh key", v.dhPub, seen.staticDhPublicKey)
            Assert.assertEquals(v.name + ": resolved generation", v.generation, seen.generation)
            Assert.assertEquals(v.name + ": resolved clock", v.created, seen.createdAtEpochSeconds)
            Assert.assertEquals(v.name + ": resolved quality", quality(v.timeQuality), seen.timeQuality)
            Assert.assertArrayEquals(v.name + ": resolved nonce", v.nonce, seen.messageNonce)
            Assert.assertArrayEquals(v.name + ": resolved body", v.body, seen.bodyUtf8)
            Assert.assertArrayEquals(v.name + ": resolved unsigned span", v.unsigned, seen.unsignedPayload)
            val round = FrameV2.decode(frame.encode())
            Assert.assertNotNull(v.name + ": the codec round-trips the signed envelope", round)
            Assert.assertArrayEquals(v.name + ": the codec carries the signature whole",
                frame.payload, round!!.payload)
        }
    }

    // ------------------------------------------------------------------ W2 zero signature

    /** W2 -- the structural golden shape with the all-zero signature slot is
     *  a STRUCTURAL fixture (section 15 keeps it): the validator passes it,
     *  runtime authentication refuses it by the named reason. */
    @Test
    fun testRuntimeRejectsZeroSignatureStructuralFixture() {
        val v = locateVectors().first { it.name == "accept_signed_ok_min" }
        val zeroed = v.payload.copyOf()
        for (k in 4 until 68) zeroed[k] = 0
        val frame = frameOf(TypeV2.SOS, 0x0030, v.msgId, zeroed)
        Assert.assertEquals("the structural gate must not be the one that speaks",
            SosFrameValidator.Verdict.OK, SosFrameValidator.validate(frame))
        rejectWithReason(SignedSosV1.verify(frame, null), "signature",
            "the all-zero signature slot authenticates against no key")
        val fromTable = locateVectors().first { it.name == "reject_zero_signature_structural_only" }
        Assert.assertArrayEquals("the pinned zero-signature vector matches the spliced shape",
            fromTable.payload, zeroed)
        rejectWithReason(SignedSosV1.verify(frameOf(TypeV2.SOS, 0x0030, v.msgId, fromTable.payload), null),
            fromTable.reason, "table vector " + fromTable.name)
    }

    // ------------------------------------------------------------------ W3 changed key/body/msgID

    /** W3 -- changed key, changed body, changed msgID all break
     *  authentication, with the reason table naming each gate; the same frame
     *  checked against a person it was not bound to is refused apart. */
    @Test
    fun testChangesToKeyBodyOrMsgIdBreakAuthentication() {
        val table = locateVectors().filter { it.kind == "reject" }
        for (n in listOf("reject_signature_bit_flip", "reject_body_bit_flip", "reject_msg_id_bit_flip")) {
            val v = table.first { it.name == n }
            rejectWithReason(SignedSosV1.verify(
                frameOf(TypeV2.SOS, 0x0030, if (n == "reject_msg_id_bit_flip")
                    flippedCopy(v.msgId, 0) else v.msgId, v.payload), null),
                v.reason, "table vector " + n)
        }
        // the header msg_id of the flip vector must actually differ where the
        // table says so: the pinned base frame authenticates until the field
        // is censored one bit at a time.
        val base = locateVectors().first { it.name == "accept_signed_ok_min" }
        val honest = SignedSosV1.verify(frameOf(TypeV2.SOS, 0x0030, base.msgId, base.payload), null)
        Assert.assertTrue("the untouched frame authenticates", honest is SosAuthResult.Authenticated)
        // changed key: the same declaration signed under a stranger's seed is
        // a different frame; under the victim's expectation it is refused.
        val strangerSeed = hexBytes(t38Repeat("a9", 32))
        val strangerPub = Ed25519Keys.publicKeyFromPrivate(strangerSeed)
        Assert.assertTrue("a different key yields a different signature",
            !strangerPub.contentEquals(base.signPub))
        // verified person separation: right frame, wrong claimed person.
        rejectWithReason(SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, base.msgId, base.payload), base.node.copyOf().also { it[0] = (it[0].toInt() xor 0x01).toByte() }),
            "identity_binding", "the frame checked against a person it was not bound to")
    }

    private fun flippedCopy(source: ByteArray, at: Int): ByteArray {
        val out = source.copyOf()
        out[at] = (out[at].toInt() xor 0x01).toByte()
        return out
    }


    // ------------------------------------------------------------------ W4 fake SOS, one bit away

    /** W4 -- a fake SOS by a one-bit type change: the renumbering is such
     *  that no assigned type is one bit from SOS, the codec fails closed on
     *  the unassigned neighbour, and a frame promoted by hand is refused by
     *  the type gate before any magic or signature is consulted. */
    @Test
    fun testFakeSosByOneBitTypeChangeRefused() {
        for (t in TypeV2.entries) {
            if (t == TypeV2.SOS) continue
            Assert.assertTrue("no assigned type sits one bit from SOS: " + t.name,
                Integer.bitCount(t.code.toInt() and 0xFF xor 0xF0) != 1)
        }
        val v = locateVectors().first { it.name == "accept_signed_ok_min" }
        val raw = frameOf(TypeV2.SOS, 0x0030, v.msgId, v.payload).encode()
        raw[3] = (raw[3].toInt() xor 0x10).toByte() // 0xF0 -> 0xE0, one bit
        val crc = FrameV2.crc16(raw, 0, 30)
        raw[30] = ((crc ushr 8) and 0xFF).toByte()
        raw[31] = (crc and 0xFF).toByte()
        Assert.assertNull("the codec refuses the promoted neighbour outright", FrameV2.decode(raw))
        // the table's own promotion vector: wrong_type is its first named reason
        val promo = locateVectors().first { it.name == "reject_one_bit_type_promotion" }
        Assert.assertEquals("the table keeps the promoted type octet", 0xE0, promo.headerType)
        // and a hand-promoted frame presented directly to the validator is
        // refused by type, never by magic: the type gate runs first.
        val asMessage = frameOf(TypeV2.MESSAGE, 0x0030, v.msgId, v.payload)
        Assert.assertEquals("the type gate precedes the magic gate",
            SosFrameValidator.Verdict.WRONG_TYPE, SosFrameValidator.validate(asMessage))
        rejectWithReason(SignedSosV1.verify(asMessage, null), "wrong_type",
            "a MESSAGE wearing SOS clothing is refused")

        // required flags: a frame born without ACK_REQ|RELAY_OK is refused by the
        // named gate -- the frozen table's required flags are load-bearing, not
        // advisory, and the roster's RC5 demands this leg be walked, not waved.
        val flagsVec = locateVectors().first { it.name == "reject_flags_missing_required" }
        Assert.assertEquals("the table keeps the deficient flag word", 0x0010,
            flagsVec.headerFlags)
        rejectWithReason(SignedSosV1.verify(
            frameOf(TypeV2.SOS, flagsVec.headerFlags, flagsVec.msgId, flagsVec.payload), null),
            flagsVec.reason, "the flags arm the verdict")
    }

    // ------------------------------------------------------------------ W5 malformed binding

    /** W5 -- malformed bindings: truncated shapes, a lying version byte, a
     *  stranger's seal upon the victim's declaration, and a key that does not
     *  hash to the claimed node all refuse with the named reasons; the same
     *  self-consistent stranger frame authenticates as the stranger's own
     *  distress when no person is claimed. */
    @Test
    fun testMalformedIdentityBindingRefused() {
        for (n in listOf("reject_truncated_binding", "reject_bad_payload_version")) {
            val v = locateVectors().first { it.name == n }
            rejectWithReason(SignedSosV1.verify(
                frameOf(TypeV2.SOS, 0x0030, v.msgId, v.payload), null),
                v.reason, "table vector " + n + " (shape gates speak in order)")
        }
        val strangerSealed = locateVectors()
            .first { it.name == "reject_stranger_key_in_binding" }
        rejectWithReason(SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, strangerSealed.msgId, strangerSealed.payload), null),
            "identity_binding", "a stranger's seal cannot certify the victim")
        val underived = locateVectors().first { it.name == "reject_underived_node_claim" }
        rejectWithReason(SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, underived.msgId, underived.payload), underived.node),
            "identity_binding", "the claim must be derived, never trusted")
        val own = SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, underived.msgId, underived.payload), null)
        Assert.assertTrue("the same frame is the stranger's own honest distress",
            own is SosAuthResult.Authenticated)
        val view = (own as SosAuthResult.Authenticated).verified
        Assert.assertArrayEquals("its key hashes to the node it names", view.senderNodeId,
            SignedSosV1.nodeIdOfSigningKey(view.signingPublicKey))
        // the binding parser itself is fail-closed: 132 bytes cannot parse
        var refused = false
        try {
            IdentityBindingV1.parse(underived.payload.copyOfRange(69, 201))
        } catch (e: IllegalArgumentException) {
            refused = true
        }
        Assert.assertTrue("IdentityBindingV1.parse refuses a truncated serialization", refused)
    }

    // ------------------------------------------------------------------ W6 the binding equation

    /** W6 -- the local public key is bound to the identity binding: every
     *  octet of the 133-byte serialization sits where the table says, the
     *  node id is the BLAKE2s-128 of the embedded key, and the authenticated
     *  key is distinguished from the verified person -- no trust or approval
     *  state moves on the authentication path, and the printed form keeps
     *  key material redacted. */
    @Test
    fun testBindsLocalPublicKeyToIdentityBinding() {
        val v = locateVectors().first { it.name == "accept_signed_ok_min" }
        val b = v.binding
        Assert.assertEquals("binding length", 133, b.size)
        Assert.assertEquals("binding version", 0x01, b[0].toInt() and 0xFF)
        for (k in 0 until 4) Assert.assertEquals("generation octet " + k,
            ((v.generation ushr (24 - 8 * k)) and 0xFF).toInt(), b[1 + k].toInt() and 0xFF)
        Assert.assertArrayEquals("embedded signing key", v.signPub, b.copyOfRange(5, 37))
        Assert.assertArrayEquals("embedded dh key", v.dhPub, b.copyOfRange(37, 69))
        Assert.assertEquals("binding seal length", 64, b.copyOfRange(69, 133).size)
        Assert.assertArrayEquals("the node id IS the hash of the embedded key",
            v.node, SignedSosV1.nodeIdOfSigningKey(v.signPub))
        val verdict = SignedSosV1.verify(frameOf(TypeV2.SOS, 0x0030, v.msgId, v.payload), v.node)
        val view = verdict as? SosAuthResult.Authenticated
        Assert.assertNotNull("the bound key authenticates against the claim", view)
        Assert.assertArrayEquals("the resolved key is the local key", v.signPub, view!!.verified.signingPublicKey)
        Assert.assertArrayEquals("the resolved node is the derivation", v.node, view.verified.senderNodeId)
        val printed = view.verified.toString()
        Assert.assertTrue("the printed form redacts key material",
            Regex("[0-9a-f]{32,}").find(printed) == null)
        Assert.assertTrue("the seed never appears in prose",
            printed.contains("b1b1b1b1").not())
    }

    // ------------------------------------------------------------------ W7 body bounds

    /** W7 -- the UTF-8 body is bound: it is carried whole into the hash, the
     *  budget is 400, malformed sequences are refused by the author before
     *  any signature is struck, and a lying length field is caught by the
     *  length gate BEFORE the signature gate may speak. */
    @Test
    fun testUtf8BodyIsBoundAndBudgeted() {
        val v = locateVectors().first { it.name == "accept_signed_ok_max_body" }
        Assert.assertEquals("the pinned body is 398 bytes of multibyte text", 398, v.body.size)
        val frame = SignedSosV1.author(v.seed, v.dhPub, v.generation, v.created,
            quality(v.timeQuality), v.nonce, v.body)
        Assert.assertEquals("the envelope carries magic, seal and the whole body",
            4 + 64 + 157 + 398, frame.payload.size)
        val verdict = SignedSosV1.verify(frame, v.node)
        Assert.assertTrue("the body survives the round trip whole",
            (verdict as? SosAuthResult.Authenticated)?.verified?.bodyUtf8?.contentEquals(v.body) == true)
        for (bad in listOf(byteArrayOf(0x80.toByte()), byteArrayOf(0xC0.toByte(), 0x80.toByte()),
            byteArrayOf(0xE0.toByte(), 0x80.toByte(), 0x80.toByte()),
            byteArrayOf(0xED.toByte(), 0xA0.toByte(), 0x80.toByte()),
            byteArrayOf(0xF0.toByte(), 0x80.toByte(), 0x80.toByte(), 0x80.toByte()),
            byteArrayOf(0xF5.toByte(), 0x80.toByte(), 0x80.toByte(), 0x80.toByte()),
            ByteArray(401) { 0x61 })) {
            var refused = false
            try {
                SignedSosV1.author(v.seed, v.dhPub, v.generation, 1700000201,
                    TimeQuality.USER_CONFIRMED, v.nonce, bad)
            } catch (e: IllegalArgumentException) {
                refused = true
            }
            Assert.assertTrue("the author refuses to strike a non-canonical body", refused)
        }
        val liar = locateVectors().first { it.name == "reject_body_length_liar" }
        rejectWithReason(SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, liar.msgId, liar.payload), null),
            "body_length", "the length gate speaks before the signature")
    }

    // ------------------------------------------------------------------ W8 duplicate resend

    /** W8 -- a duplicate logical SOS: the same immutable identity re-sent
     *  yields the identical frame (no re-derivation, no re-signature drift on
     *  this isle), and the composing node's seen-cache admits the indication
     *  to the observer exactly once. */
    @Test
    fun testDuplicateLogicalSosResentIdempotent() = runTest {
        val v = locateVectors().first { it.name == "accept_signed_ok_min" }
        val first = SignedSosV1.author(v.seed, v.dhPub, v.generation, v.created,
            quality(v.timeQuality), v.nonce, v.body)
        val second = SignedSosV1.author(v.seed, v.dhPub, v.generation, v.created,
            quality(v.timeQuality), v.nonce, v.body)
        Assert.assertArrayEquals("the resend is bit-identical: the identity is immutable",
            first.msgId, second.msgId)
        Assert.assertArrayEquals("the resend carries the same seal", first.payload, second.payload)
        val store = InMemoryMessageStore()
        val observer = Watcher()
        var node = newComposingNode(store, observer)
        val hop = ByteArray(16) { 0x5A.toByte() }
        Assert.assertTrue("the novel frame is relayed", node.handleInboundFrame(hop, first.encode()))
        Assert.assertFalse("the duplicate is deduped by the seen cache",
            node.handleInboundFrame(hop, second.encode()))
        Assert.assertEquals("the honest bytes authenticate again, idempotently",
            2, observer.authenticated)
        Assert.assertEquals("no refusal was recorded", 0, observer.unauthenticated)
        Assert.assertEquals("the seen cache governs repetition: held once", 1,
            store.allHeldMsgIds().size)
    }

    private fun newComposingNode(store: InMemoryMessageStore, observer: Watcher?): MeshNode {
        val node = MeshNode(
            ctx = null,
            identity = newIdentity(),
            store = store,
            deliveryTracker = DeliveryTracker(deadRepo(),
                Ed25519AckAuthenticator(UnresolvedRecipientKeyResolver)),
        )
        node.sosObserver = observer
        return node
    }

    // ------------------------------------------------------------------ W9 unknown-time pairing

    /** W9 -- the unknown-time rule binds the clock and the quality: zero with
     *  a claimed quality, or a real clock with UNKNOWN, are authoring errors
     *  and reception refusals alike; the honest pairing verifies. */
    @Test
    fun testUnknownTimeQualityPairingEnforced() {
        val v = locateVectors().first { it.name == "accept_signed_ok_min" }
        var threwOne = false
        try {
            SignedSosV1.author(v.seed, v.dhPub, v.generation, 0, TimeQuality.USER_CONFIRMED,
                v.nonce, v.body)
        } catch (e: IllegalArgumentException) {
            threwOne = true
        }
        Assert.assertTrue("zero clock with a claimed quality is not stricken", threwOne)
        var threwOther = false
        try {
            SignedSosV1.author(v.seed, v.dhPub, v.generation, 1700000201, TimeQuality.UNKNOWN,
                v.nonce, v.body)
        } catch (e: IllegalArgumentException) {
            threwOther = true
        }
        Assert.assertTrue("a running clock with UNKNOWN is not stricken", threwOther)
        val unpaired = locateVectors().first { it.name == "reject_unknown_time_pairing" }
        rejectWithReason(SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, unpaired.msgId, unpaired.payload), null),
            "unknown_time_pairing", "broken pairing is refused at reception too")
        val rogue = locateVectors().first { it.name == "reject_unknown_time_quality" }
        rejectWithReason(SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, rogue.msgId, rogue.payload), null),
            "time_quality", "no quality beyond the closed table")
        val honest = locateVectors().first { it.name == "accept_unknown_time_zero_clock" }
        val verdict = SignedSosV1.verify(
            frameOf(TypeV2.SOS, 0x0030, honest.msgId, honest.payload), null)
        Assert.assertTrue("the honest pairing of zero clock with UNKNOWN verifies",
            (verdict as? SosAuthResult.Authenticated)?.verified?.timeQuality == TimeQuality.UNKNOWN)
    }

    // ------------------------------------------------------------------ W10 composed authorship

    /** W10 -- composed authorship: with the authority wired, MeshNode's SOS
     *  dispatch sends a frame that authenticates under the node's own bound
     *  key and carries the user's body whole; without it the node still
     *  emits the legacy structural shape, which the receiver's runtime
     *  authentication refuses. */
    @Test
    fun testComposedNodeAuthorsSignedDistress() = runTest {
        val v = locateVectors().first { it.name == "accept_signed_ok_min" }
        val store = InMemoryMessageStore()
        val journal = T38Journal()
        val node = MeshNode(
            ctx = null,
            identity = newIdentity(),
            store = store,
            deliveryTracker = DeliveryTracker(journal,
                Ed25519AckAuthenticator(UnresolvedRecipientKeyResolver)),
        )
        val authority = FakeAuthority(v.seed, v.dhPub, v.generation, v.created, v.nonce)
        node.sosAuthority = authority
        val peers = ArrayList<ByteArray>()
        val sent = ArrayList<ByteArray>()
        node.injectPeerForTest(ByteArray(16) { 0x21.toByte() })
        val result = node.dispatchSos(ascii("mayday-mayday")) { peer, bytes ->
            peers.add(peer.copyOf()); sent.add(bytes.copyOf()); true
        }
        Assert.assertTrue("the distress was handed to relays",
            result is SosDispatchResult.HandedToRelays)
        Assert.assertEquals("one send", 1, sent.size)
        val frame = FrameV2.decode(sent[0])
        Assert.assertNotNull("the send decodes", frame)
        val verdict = SignedSosV1.verify(frame!!, v.node)
        val ok = verdict as? SosAuthResult.Authenticated
        Assert.assertNotNull("the composed node's frame authenticates under the bound key", ok)
        Assert.assertArrayEquals("the body was carried whole", ascii("mayday-mayday"),
            ok!!.verified.bodyUtf8)
        Assert.assertArrayEquals("the sender is the node that holds the key", v.node, ok.verified.senderNodeId)
        Assert.assertEquals("the generation is the authority's", v.generation, ok.verified.generation)
        Assert.assertEquals("the authority was consulted", 1, authority.calls)
        Assert.assertTrue("the node holds what it sent",
            store.allHeldMsgIds().any { it.contentEquals(frame.msgId) })
        // the captured side effect of the C6 sender leg: exactly one durable
        // delivery record, mode NONE, no recipient bound (a none-mode message
        // can never be acknowledged), and it advanced to handed-after-relay.
        Assert.assertEquals("one delivery record", 1, journal.records.size)
        val rec = journal.records[frame.msgId.toList()]
        Assert.assertNotNull("the record is keyed by the authored msg_id", rec)
        Assert.assertEquals("the distress is broadcast: mode none", AckMode.NONE, rec!!.ackMode)
        Assert.assertNull("none-mode binds no recipient", rec.expectedRecipientNodeId)
        Assert.assertEquals("the hand-off was recorded", DeliveryState.HANDED_TO_RELAY, rec.state)
        // the legacy arm: unwired authority, the structural shape still goes
        // out (documented) and the receiver refuses it by the named reason.
        val bareJournal = T38Journal()
        val bare = MeshNode(
            ctx = null,
            identity = newIdentity(),
            store = InMemoryMessageStore(),
            deliveryTracker = DeliveryTracker(bareJournal,
                Ed25519AckAuthenticator(UnresolvedRecipientKeyResolver)),
        )
        bare.injectPeerForTest(ByteArray(16) { 0x22.toByte() })
        var legacy: ByteArray? = null
        bare.dispatchSos(ascii("old-style")) { _, bytes -> legacy = bytes.copyOf(); true }
        val legacyFrame = FrameV2.decode(legacy!!)
        Assert.assertNotNull("the legacy shape still decodes", legacyFrame)
        Assert.assertEquals("the structural gate passes it", SosFrameValidator.Verdict.OK,
            SosFrameValidator.validate(legacyFrame!!))
        // the legacy buildSos shape is thin: magic, an empty 64-byte slot and
        // the bare user bytes -- it does not even carry the fixed signed
        // structure, so the length gate (first among equals) refuses it as
        // malformed before the seal is weighed. The well-formed zero-seal
        // case, where the receiver must name the signature gate, is W2.
        rejectWithReason(SignedSosV1.verify(legacyFrame, null), "malformed",
            "the legacy structural shape is refused before the seal is weighed")
        Assert.assertEquals("the legacy arm also keeps the C6 ledger", 1, bareJournal.records.size)
        Assert.assertEquals("broadcast remains mode none on every arm", AckMode.NONE,
            bareJournal.records.values.first().ackMode)
    }

    // ------------------------------------------------------------------ W11 inbound relay truth

    /** W11 -- the relay decides first and on its own; authentication rides
     *  beside it. An unauthenticated frame is never promoted to the
     *  observer, a trusted-looking forgery is refused by the named gate, the
     *  delivery tracker is never reached by an inbound SOS, and no ACK is
     *  ever issued for a mode-none message. */
    @Test
    fun testInboundRelayTruthUntouchedAndUnauthenticatedNeverPromoted() = runTest {
        val store = InMemoryMessageStore()
        val observer = Watcher()
        val node = newComposingNode(store, observer)
        val hop = ByteArray(16) { 0x67.toByte() }
        val honest = locateVectors().first { it.name == "accept_signed_ok_min" }
        Assert.assertTrue("the honest frame is relayed on its own merits",
            node.handleInboundFrame(hop, honest.payload.let {
                frameOf(TypeV2.SOS, 0x0030, honest.msgId, it).encode()
            }))
        Assert.assertEquals("the observer saw the authenticated indication", 1, observer.authenticated)
        Assert.assertEquals("no refusal for the honest one", 0, observer.unauthenticated)
        // a forgery on the honest identity: same msg_id, one bit flipped in
        // the signature region. The seen cache guards repetition (the relay
        // returns false and nothing persists twice), yet the observer hook
        // still runs and the signature gate names the refusal.
        val forgedPayload = flippedCopy(honest.payload, 9)
        Assert.assertFalse("the forgery shares the held msg_id: deduped at the cache",
            node.handleInboundFrame(hop, frameOf(TypeV2.SOS, 0x0030, honest.msgId, forgedPayload).encode()))
        Assert.assertEquals("the forgery was never announced as authenticated", 1,
            observer.authenticated)
        Assert.assertEquals("the refusal was recorded once", 1, observer.unauthenticated)
        Assert.assertEquals("by the named gate", "signature", observer.lastReason)
        // no ACK was ever issued for a mode-none distress: the ack namespace
        // stays empty and the tracker's dead methods would have thrown.
        Assert.assertEquals("no ack rows for a broadcast", 0, store.ackStore.countFrames())
        Assert.assertEquals("the held set is exactly the one honest frame", 1,
            store.allHeldMsgIds().size)
        // the resend of the honest frame: deduped at the cache, yet the hook
        // re-authenticates the same honest bytes -- authentication is
        // idempotent per observation; the indication is announced again.
        Assert.assertFalse("the resend is deduped", node.handleInboundFrame(hop,
            frameOf(TypeV2.SOS, 0x0030, honest.msgId, honest.payload).encode()))
        Assert.assertEquals("the honest bytes authenticate again, idempotently", 2,
            observer.authenticated)
        Assert.assertEquals("and the refusal count stays at one", 1, observer.unauthenticated)
    }
}
// (file-scoped helper appended below the class for this court only)
private fun t38Repeat(unit: String, times: Int): String {
    val sb = StringBuilder(unit.length * times)
    for (k in 0 until times) sb.append(unit)
    return sb.toString()
}
